const input = $input.first().json;
const query = input.query || {};

const projectId = query.project_id || 'unknown';
const action = query.action || 'success';
const sessionId = query.session_id || null;

// Configuration par action
const config = {
  success: {
    title: 'Paiement réussi!',    icon: '✅',
    message: 'Votre abonnement a été activé avec succès.',
    subMessage: 'Vous pouvez maintenant profiter de toutes les fonctionnalités premium.',
    color: '#10B981'
  },
  cancel: {
    title: 'Paiement annulé',
    icon: '❌',
    message: "Le paiement a été annulé.",
    subMessage: "Vous pouvez réessayer à tout moment depuis Discord.",
    color: '#EF4444'
  },
  portal: {
    title: 'Gestion terminée',
    icon: '⚙️',
    message: 'Vos modifications ont été enregistrées.',
    subMessage: 'Vous pouvez fermer cette page et retourner sur Discord.',
    color: '#6366F1'
  }
};

const cfg = config[action] || config.success;

return [{
  json: {
    project_id: projectId,
    action: action,
    session_id: sessionId,
    ...cfg
  }
}];

